const remote=window.siteDb;
const byId=id=>document.getElementById(id);
const state=byId('online-status');
const login=byId('online-login');
const panel=byId('online-panel');
let onlineRecords=[];

function status(text){state.textContent=text;byId('online-feedback').textContent=text;}
function syncImageFields(){const study=byId('online-type').value==='study';byId('online-image-fields').hidden=!study;for(const id of ['online-image','online-alt','online-credit'])byId(id).disabled=!study;}
function getForm(){const study=byId('online-type').value==='study';return {id:byId('online-id').value||undefined,entry_type:byId('online-type').value,title:byId('online-title').value,category:byId('online-category').value,body:byId('online-body').value,image_url:study?byId('online-image').value:'',image_alt:study?byId('online-alt').value:'',credit:study?byId('online-credit').value:'',is_demo:byId('online-demo').checked,is_published:byId('online-published').checked};}
function clearForm(){byId('online-editor').reset();syncImageFields();byId('online-id').value='';byId('online-title').focus();}
function openRecord(r){byId('online-id').value=r.id;byId('online-type').value=r.entry_type;syncImageFields();byId('online-title').value=r.title;byId('online-category').value=r.category;byId('online-body').value=r.body;byId('online-image').value=r.image_url||'';byId('online-alt').value=r.image_alt||'';byId('online-credit').value=r.credit||'';byId('online-demo').checked=r.is_demo;byId('online-published').checked=r.is_published;byId('online-title').focus();}
function render(){const list=byId('online-list');list.replaceChildren();if(!onlineRecords.length){list.textContent='Ainda não há itens online.';return;}for(const r of onlineRecords){const row=document.createElement('div');row.className='online-row';const name=document.createElement('strong');name.textContent=r.title;const badge=document.createElement('span');badge.textContent=(r.entry_type==='study'?'Estudo':'Artigo')+' · '+(r.is_published?'Publicado':'Rascunho')+(r.is_demo?' · Demonstração':'');const edit=document.createElement('button');edit.type='button';edit.textContent='Editar';edit.onclick=()=>openRecord(r);const remove=document.createElement('button');remove.type='button';remove.textContent='Excluir';remove.onclick=async()=>{if(!confirm(`Excluir “${r.title}” do banco?`))return;try{await remote.remove(r.id);status('Item excluído do Supabase.');await refresh();}catch(error){status('Não foi possível excluir: '+error.message);}};row.append(name,badge,edit,remove);list.append(row);}}
async function refresh(){onlineRecords=await remote.all();render();}
async function updateSession(){try{await remote.published();const {data,error}=await remote.client.auth.getUser();if(error&&error.name!=='AuthSessionMissingError')throw error;const user=data?.user;const isOwner=user?.email?.toLowerCase()===remote.ownerEmail;login.hidden=!!user;panel.hidden=!isOwner;if(isOwner){status('Conectado como '+remote.ownerEmail+'.');await refresh();}else if(user){status('Esta conta não tem permissão para editar o portfólio.');login.hidden=true;}else status('Entre para editar e publicar.');}catch(error){login.hidden=true;panel.hidden=true;status('Aguarde a configuração da tabela no Supabase para usar o painel online.');}}

byId('send-link').onclick=async()=>{const button=byId('send-link');button.disabled=true;status('Enviando link de acesso…');try{const {error}=await remote.client.auth.signInWithOtp({email:remote.ownerEmail,options:{emailRedirectTo:new URL('admin.html',location.href).href}});if(error)throw error;status('Enviamos um link de acesso para '+remote.ownerEmail+'. Confira o e-mail.');}catch(error){status('Não foi possível enviar o link: '+error.message);}finally{button.disabled=false;}};
byId('sign-out').onclick=async()=>{await remote.client.auth.signOut();await updateSession();};
byId('online-type').onchange=syncImageFields;
byId('online-new').onclick=clearForm;
byId('online-editor').onsubmit=async event=>{event.preventDefault();const record=getForm();if(record.entry_type==='study'&&record.is_published){if(!record.image_url||!record.image_alt||!record.credit){status('Para publicar um estudo, inclua imagem, descrição e crédito.');return;}if(!record.image_url.startsWith('https://')){status('Use um endereço HTTPS para a imagem.');return;}}if(record.image_url&&!record.image_url.startsWith('https://')){status('Use um endereço HTTPS para a imagem.');return;}try{const saved=await remote.save(record);byId('online-id').value=saved.id;status(saved.is_published?'Item publicado. Atualize o site para vê-lo.':'Rascunho guardado no Supabase.');await refresh();}catch(error){status('Não foi possível guardar: '+error.message);}};
remote.client.auth.onAuthStateChange(()=>{setTimeout(updateSession,0);});
syncImageFields();
updateSession();
